	/** 
	 * jumpstart the process by instantiating2 Lot
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		lotId = LotService.getLotInstance()
		.createLot( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		LotService.getLotInstance()
				.createLot( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.lotSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Lot : " + successValue.getLotId());
							  if (successValue.getLotId().equals(lotId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfLotList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Lot test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on lot consumed")
					);
			subscriber.lotSubscribe( lotId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Lot : " + successValue.getLotId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfLotList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on lot for lotId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Lot. 
	 */
	protected Lot read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Lot" );

		Lot entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Lot with primary key" );
		msg.append( lotId );
		
		LotFetchOneSummary fetchOneSummary = new LotFetchOneSummary( lotId );

		try {
			entity = LotService.getLotInstance().getLot( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Lot " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Lot.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Lot." );

		StringBuilder msg = new StringBuilder( "Failed to update a Lot : " );        
		Lot entity = read();
		UpdateLotCommand command = generateUpdateCommand();
		command.setLotId(entity.getLotId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Lot." );

			// for use later on...
			lotId = entity.getLotId();

			LotService proxy = LotService.getLotInstance();  

			proxy.updateLot( command ).get();

			LOGGER.info( "-- Successfully saved Lot - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + lotId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Lot.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Lot." );

		Lot entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Lot with id " + lotId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Lot with id " + lotId );

			throw e;
		}

		try{
			LotService.getLotInstance().delete( new DeleteLotCommand( entity.getLotId() ) ).get();
			LOGGER.info( "-- Successfully deleted Lot with id " + lotId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Lot with id " + lotId );

			throw e;
		}
	}

	/**
	 * get all Lots.
	 */
	protected List<Lot> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Lots:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Lot : " );        
		List<Lot> collection  = new ArrayList<>();

		try {
			// call the static get method on the LotService
			collection = LotService.getLotInstance().getAllLot();
			assertNotNull( collection, "An Empty collection of Lot was incorrectly returned.");
			
			// Now print out the values
			Lot entity = null;            
			Iterator<Lot> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getLotId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

